import React from 'react';
import { motion } from 'framer-motion';

const FEATURE_NAMES = {
  'SMA_20':      '20-Day SMA',
  'SMA_50':      '50-Day SMA',
  'SMA_200':     '200-Day SMA',
  'EMA_12':      '12-Day EMA',
  'EMA_26':      '26-Day EMA',
  'RSI_14':      'RSI (14)',
  'MACD':        'MACD',
  'MACD_Signal': 'MACD Signal',
  'BB_Upper':    'BB Upper',
  'BB_Lower':    'BB Lower',
  'ATR_14':      'ATR (14)',
  'Volume_SMA':  'Vol. SMA',
  'Daily_Return':'Daily Ret.',
  'Volatility':  'Volatility',
  'High_Low_Pct':'H/L Range',
};

const FeatureImportance = ({ features }) => {
  if (!features?.length) return null;
  const maxAbs = Math.max(...features.map(f => Math.abs(f.impact)), 1e-9);

  return (
    <motion.div
      className="card feature-importance-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.1 }}
    >
      <div className="card-title">
        <div className="card-ico ico-c">🔑</div>
        <span className="card-title-text">SHAP Attribution Analysis</span>
      </div>

      <div className="feature-list">
        {features.map((f, i) => {
          const isPos = f.impact >= 0;
          const pct   = (Math.abs(f.impact) / maxAbs) * 100;
          const displayName = FEATURE_NAMES[f.name] || f.name;
          return (
            <motion.div
              key={f.name}
              className="feature-item-row"
              initial={{ opacity: 0, x: -16 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.15 + i * 0.07 }}
            >
              <div className="feature-header">
                <span className="feature-name">{i + 1}. {displayName}</span>
                <span className={`feature-impact ${isPos ? 'positive' : 'negative'}`}>
                  {isPos ? '↗ Bullish' : '↘ Bearish'}
                </span>
              </div>
              <div className="feature-bar">
                <motion.div
                  className={`feature-bar-fill ${isPos ? 'positive' : 'negative'}`}
                  initial={{ width: 0 }}
                  animate={{ width: `${pct}%` }}
                  transition={{ duration: 0.9, delay: 0.25 + i * 0.07 }}
                />
              </div>

              {/* ISSUE 5 FIX: Show SHAP context — value, percentile, contribution % */}
              <div style={{
                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                fontSize: 10, fontFamily: 'JetBrains Mono,monospace', marginTop: 2
              }}>
                <span style={{ color: isPos ? 'var(--green)' : 'var(--red)' }}>
                  SHAP: {f.impact >= 0 ? '+' : ''}{f.impact.toFixed(5)}
                </span>
                <span style={{ color: 'var(--dim)', display: 'flex', gap: 8 }}>
                  {f.pct_contribution != null && (
                    <span title="% of total prediction variance explained by this feature">
                      {f.pct_contribution.toFixed(1)}% contrib.
                    </span>
                  )}
                  {f.pct_rank != null && (
                    <span title="Current value's percentile rank in the 60-day window">
                      P{f.pct_rank.toFixed(0)}
                    </span>
                  )}
                  {f.context_value != null && (
                    <span title="Current normalized value of this feature">
                      val={f.context_value.toFixed(3)}
                    </span>
                  )}
                </span>
              </div>
            </motion.div>
          );
        })}
      </div>

      <div className="tip-box">
        💡 SHAP values quantify per-feature attribution (Lundberg & Lee, 2017). <strong style={{color:'var(--green)'}}>+</strong> = bullish push, <strong style={{color:'var(--red)'}}>−</strong> = bearish push. P<em>n</em> = percentile rank in 60-day window.
      </div>
    </motion.div>
  );
};

export default FeatureImportance;
